<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { fetchComplaint, fetchComplaints, processComplaint } from '@/api/complaints'
import { useAuthStore } from '@/stores/auth'
import type { Complaint, ComplaintResolutionType, ComplaintStatus } from '@/types/api'

const auth = useAuthStore(); const router = useRouter(); const page = ref(1); const size = 20; const total = ref(0); const status = ref<ComplaintStatus | ''>(''); const records = ref<Complaint[]>([]); const loading = ref(false); const error = ref(''); const selected = ref<Complaint | null>(null); const saving = ref(false)
const form = ref<{ resolutionType: ComplaintResolutionType; refundAmount: number; content: string }>({ resolutionType: 'APOLOGY', refundAmount: 0, content: '' })
const pages = computed(() => Math.max(1, Math.ceil(total.value / size)))
const statusLabel: Record<ComplaintStatus, string> = { OPEN: '待处理', PROCESSING: '处理中', RESOLVED: '已结案' }
const resolutionLabel: Record<ComplaintResolutionType, string> = { APOLOGY: '仅道歉', PARTIAL_REFUND: '部分退款', FULL_REFUND: '全额退款', REJECT: '驳回投诉' }
async function load() { loading.value = true; error.value = ''; try { const result = await fetchComplaints({ page: page.value, size, status: status.value || undefined }); records.value = result.records; total.value = result.total; page.value = result.page } catch (reason) { error.value = reason instanceof Error ? reason.message : '加载投诉工单失败。' } finally { loading.value = false } }
async function open(item: Complaint) { try { selected.value = await fetchComplaint(item.complaintNo); form.value = { resolutionType: 'APOLOGY', refundAmount: 0, content: '' } } catch (reason) { error.value = reason instanceof Error ? reason.message : '加载投诉详情失败。' } }
function onResolutionChange() { if (form.value.resolutionType === 'APOLOGY' || form.value.resolutionType === 'REJECT') form.value.refundAmount = 0 }
async function submit() { if (!selected.value || !form.value.content.trim()) { error.value = '请填写处理说明。'; return } if ((form.value.resolutionType === 'APOLOGY' || form.value.resolutionType === 'REJECT') && form.value.refundAmount !== 0) { error.value = '该处理方式不能退款。'; return } saving.value = true; error.value = ''; try { await processComplaint(selected.value.complaintNo, { ...form.value, content: form.value.content.trim() }); selected.value = null; await load() } catch (reason) { error.value = reason instanceof Error ? reason.message : '处理投诉失败。' } finally { saving.value = false } }
function format(time: string | null) { return time ? new Date(time.replace(' ', 'T')).toLocaleString('zh-CN', { hour12: false }) : '—' }
onMounted(() => void load())
</script>
<template>
  <section class="page-content"><header><div><p class="eyebrow">售后运营</p><h1>投诉工单</h1><p>审核订单争议，记录处理说明并按规则完成余额退款。</p></div><div class="operator">{{ auth.user?.username }}<small>管理员</small></div></header><section class="panel"><div class="filters"><select v-model="status" @change="page = 1; load()"><option value="">全部状态</option><option value="OPEN">待处理</option><option value="PROCESSING">处理中</option><option value="RESOLVED">已结案</option></select></div><p v-if="error" class="error">{{ error }}</p><div class="table-wrap"><table><thead><tr><th>投诉号</th><th>订单号</th><th>类型</th><th>状态</th><th>退款</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="7" class="empty">正在加载...</td></tr><tr v-else-if="!records.length"><td colspan="7" class="empty">暂无投诉工单</td></tr><tr v-for="item in records" :key="item.complaintNo"><td>{{ item.complaintNo }}</td><td><button class="text-button" @click="router.push({ name: 'order-detail', params: { orderNo: item.orderNo } })">{{ item.orderNo }}</button></td><td>{{ item.complaintType }}</td><td><span class="status" :class="item.status.toLowerCase()">{{ statusLabel[item.status] }}</span></td><td>{{ Number(item.refundAmount).toFixed(2) }} 元</td><td>{{ format(item.createdTime) }}</td><td><button class="secondary" @click="open(item)">{{ item.status === 'RESOLVED' ? '查看' : '处理' }}</button></td></tr></tbody></table></div><footer class="pagination"><span>共 {{ total }} 条工单</span><div><button :disabled="page <= 1 || loading" @click="page--; load()">上一页</button><span>第 {{ page }} / {{ pages }} 页</span><button :disabled="page >= pages || loading" @click="page++; load()">下一页</button></div></footer></section></section><div v-if="selected" class="modal-backdrop" @click.self="selected = null"><form class="modal" @submit.prevent="submit"><div class="modal-title"><div><h2>投诉 {{ selected.complaintNo }}</h2><p>订单 {{ selected.orderNo }} · {{ selected.complaintType }}</p></div><button type="button" class="close" @click="selected = null">×</button></div><p class="complaint-content">{{ selected.content }}</p><template v-if="selected.status !== 'RESOLVED'"><label>处理结果<select v-model="form.resolutionType" @change="onResolutionChange"><option value="APOLOGY">仅道歉</option><option value="PARTIAL_REFUND">部分退款</option><option value="FULL_REFUND">全额退款</option><option value="REJECT">驳回投诉</option></select></label><label v-if="form.resolutionType === 'PARTIAL_REFUND' || form.resolutionType === 'FULL_REFUND'">退款金额（元）<input v-model.number="form.refundAmount" required type="number" min="0.01" step="0.01" /></label><label>处理说明<textarea v-model="form.content" required maxlength="1000" /></label><div class="modal-actions"><button type="button" class="secondary" @click="selected = null">取消</button><button :disabled="saving">{{ saving ? '处理中...' : '确认处理' }}</button></div></template><template v-else><p>处理结果：{{ selected.resolutionType ? resolutionLabel[selected.resolutionType] : '—' }}</p><p>退款金额：{{ Number(selected.refundAmount).toFixed(2) }} 元</p><p>结案时间：{{ format(selected.resolvedTime) }}</p></template></form></div>
</template>
